<?php
require dirname(__DIR__).'/app/bootstrap.php';
$me=require_login();
if(!can('advertising.manage')&&!can('advertising.approve')){http_response_code(403);exit('Advertising permission required. Ask a system administrator to assign Advertising Manager or Publisher.');}
$error='';
function ad_redirect(): never{header('Location: '.path('admin/advertising.php'));exit;}
function ad_currency(string $value): string{$value=strtoupper(trim($value));if(!preg_match('/^[A-Z]{3}$/',$value))throw new RuntimeException('Use a valid three-letter currency.');return $value;}
function ad_date(string $value,string $label): string{$time=strtotime(trim($value));if($time===false)throw new RuntimeException($label.' is invalid.');return date('Y-m-d H:i:s',$time);}
function ad_slots(): array{return ['homepage_right_1'=>'Homepage Right 1','homepage_right_2'=>'Homepage Right 2','homepage_right_3'=>'Homepage Right 3','homepage_right_4'=>'Homepage Right 4','sitewide_luxury_banner'=>'Sitewide Luxury Banner — all public pages'];}

if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();try{$action=(string)($_POST['action']??'');
  if($action==='create_advertiser'){
   require_permission('advertising.manage');$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$currency=ad_currency((string)($_POST['currency']??'RWF'));
   if(mb_strlen($name)<2||mb_strlen($name)>200||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Valid advertiser name and email are required.');
   db()->prepare('INSERT INTO advertisers(name,contact_email,billing_currency,status,created_by) VALUES (?,?,?,\'active\',?)')->execute([$name,$email,$currency,(int)$me['id']]);$id=(int)db()->lastInsertId();audit_log('advertiser_created','advertiser',$id,$currency);flash('Advertiser created.');
  }elseif($action==='create_campaign'){
   require_permission('advertising.manage');$advertiserId=(int)($_POST['advertiser_id']??0);$advertiser=query_one("SELECT id FROM advertisers WHERE id=? AND status='active'",[$advertiserId]);$name=trim((string)($_POST['name']??''));$model=(string)($_POST['pricing_model']??'FIXED');$budget=max(0,(int)($_POST['budget_minor']??0));$currency=ad_currency((string)($_POST['currency']??'RWF'));$starts=ad_date((string)($_POST['starts_at']??''),'Campaign start');$ends=ad_date((string)($_POST['ends_at']??''),'Campaign end');
   if(!$advertiser||mb_strlen($name)<3||!in_array($model,['CPM','CPC','FIXED'],true)||$budget<1||strtotime($ends)<=strtotime($starts))throw new RuntimeException('Valid advertiser, campaign, budget and date range are required.');
   db()->prepare("INSERT INTO ad_campaigns(advertiser_id,name,pricing_model,budget_minor,currency,starts_at,ends_at,status,created_by) VALUES (?,?,?,?,?,?,?,'draft',?)")->execute([$advertiserId,$name,$model,$budget,$currency,$starts,$ends,(int)$me['id']]);$id=(int)db()->lastInsertId();audit_log('campaign_created','ad_campaign',$id,$model);flash('Campaign draft created.');
  }elseif($action==='submit_campaign'){
   require_permission('advertising.manage');$id=(int)($_POST['id']??0);$s=db()->prepare("UPDATE ad_campaigns SET status='pending_approval' WHERE id=? AND status='draft'");$s->execute([$id]);if($s->rowCount()!==1)throw new RuntimeException('Only a draft campaign can be submitted.');audit_log('campaign_submitted','ad_campaign',$id);flash('Campaign submitted for independent approval.');
  }elseif($action==='approve_campaign'){
   require_permission('advertising.approve');$id=(int)($_POST['id']??0);$campaign=query_one('SELECT * FROM ad_campaigns WHERE id=?',[$id]);if(!$campaign||$campaign['status']!=='pending_approval')throw new RuntimeException('Campaign is not awaiting approval.');if((int)$campaign['created_by']===(int)$me['id'])throw new RuntimeException('Campaign creator cannot approve their own campaign.');$s=db()->prepare("UPDATE ad_campaigns SET status='approved',approved_by=? WHERE id=? AND status='pending_approval'");$s->execute([(int)$me['id'],$id]);if($s->rowCount()!==1)throw new RuntimeException('Campaign review changed before approval completed.');audit_log('campaign_approved','ad_campaign',$id);flash('Campaign independently approved.');
  }elseif($action==='campaign_status'){
   require_permission('advertising.manage');$id=(int)($_POST['id']??0);$to=(string)($_POST['status']??'');$campaign=query_one('SELECT * FROM ad_campaigns WHERE id=?',[$id]);if(!$campaign)throw new RuntimeException('Campaign not found.');$from=(string)$campaign['status'];$allowed=['approved'=>['active','cancelled'],'active'=>['paused','completed','cancelled'],'paused'=>['active','completed','cancelled']];if(!in_array($to,$allowed[$from]??[],true))throw new RuntimeException('Invalid campaign transition.');if($to==='active'&&(time()<strtotime($campaign['starts_at'])||time()>=strtotime($campaign['ends_at'])))throw new RuntimeException('Campaign can activate only inside its approved date range.');$s=db()->prepare('UPDATE ad_campaigns SET status=? WHERE id=? AND status=?');$s->execute([$to,$id,$from]);if($s->rowCount()!==1)throw new RuntimeException('Campaign status changed before this action completed.');audit_log('campaign_status','ad_campaign',$id,$from.'>'.$to);flash('Campaign status updated.');
  }elseif($action==='create_creative'){
   require_permission('advertising.manage');$id=AdService::create($_FILES['creative_image']??[],$_POST,(int)($_POST['campaign_id']??0),(int)$me['id']);audit_log('creative_created','ad_creative',$id,'quarantined');flash('Creative saved privately as a draft.');
  }elseif($action==='update_creative'){
   require_permission('advertising.manage');$id=(int)($_POST['id']??0);AdService::update($id,$_FILES['creative_image']??[],$_POST,(int)$me['id']);audit_log('creative_updated','ad_creative',$id,'draft');flash('Creative updated and returned to draft.');
  }elseif($action==='submit_creative'){
   require_permission('advertising.manage');$id=(int)($_POST['id']??0);$creative=query_one('SELECT cr.id,c.status campaign_status FROM ad_creatives cr JOIN ad_campaigns c ON c.id=cr.campaign_id WHERE cr.id=?',[$id]);if(!$creative||!in_array($creative['campaign_status'],['approved','active'],true))throw new RuntimeException('Campaign must be approved before creative review.');$s=db()->prepare("UPDATE ad_creatives SET status='pending_review',review_note=NULL,updated_at=".sql_now()." WHERE id=? AND status IN ('draft','rejected')");$s->execute([$id]);if($s->rowCount()!==1)throw new RuntimeException('Only draft or rejected creatives can be submitted.');audit_log('creative_submitted','ad_creative',$id);flash('Creative submitted for independent review.');
  }elseif($action==='approve_creative'){
   require_permission('advertising.approve');$id=(int)($_POST['id']??0);AdService::approve($id,(int)$me['id']);audit_log('creative_approved','ad_creative',$id);flash('Creative approved and safe derivative published.');
  }elseif($action==='reject_creative'){
   require_permission('advertising.approve');$id=(int)($_POST['id']??0);$reason=trim((string)($_POST['reason']??''));$creative=query_one("SELECT created_by FROM ad_creatives WHERE id=? AND status='pending_review'",[$id]);if(!$creative||mb_strlen($reason)<10)throw new RuntimeException('A pending creative and 10+ character reason are required.');if((int)$creative['created_by']===(int)$me['id'])throw new RuntimeException('Creative creator cannot review their own creative.');db()->prepare("UPDATE ad_creatives SET status='rejected',review_note=?,approved_by=?,approved_at=".sql_now().',updated_at='.sql_now().' WHERE id=?')->execute([substr($reason,0,1000),(int)$me['id'],$id]);audit_log('creative_rejected','ad_creative',$id,$reason);flash('Creative rejected with review note.');
  }elseif($action==='save_placement'){
   require_permission('advertising.manage');$id=(int)($_POST['id']??0);$creativeId=(int)($_POST['creative_id']??0);$slot=(string)($_POST['slot_key']??'');$starts=ad_date((string)($_POST['starts_at']??''),'Placement start');$ends=ad_date((string)($_POST['ends_at']??''),'Placement end');$creative=query_one("SELECT cr.id,cr.status,c.starts_at campaign_start,c.ends_at campaign_end,c.status campaign_status FROM ad_creatives cr JOIN ad_campaigns c ON c.id=cr.campaign_id WHERE cr.id=?",[$creativeId]);
   if(!$creative||$creative['status']!=='approved'||!in_array($creative['campaign_status'],['approved','active','paused'],true)||!isset(ad_slots()[$slot])||strtotime($ends)<=strtotime($starts))throw new RuntimeException('Approved creative, valid slot and date range are required.');if(strtotime($starts)<strtotime($creative['campaign_start'])||strtotime($ends)>strtotime($creative['campaign_end']))throw new RuntimeException('Placement dates must remain inside campaign dates.');
   $overlap=query_one("SELECT id FROM ad_placements WHERE slot_key=? AND id<>? AND status IN ('draft','active','paused') AND starts_at<? AND ends_at>? LIMIT 1",[$slot,$id,$ends,$starts]);if($overlap)throw new RuntimeException('That homepage slot already has an overlapping placement.');
   if($id){$s=db()->prepare("UPDATE ad_placements SET creative_id=?,slot_key=?,starts_at=?,ends_at=?,status='draft',updated_by=?,updated_at=".sql_now()." WHERE id=? AND status IN ('draft','paused')");$s->execute([$creativeId,$slot,$starts,$ends,(int)$me['id'],$id]);if($s->rowCount()!==1)throw new RuntimeException('Only draft or paused placements can be edited.');}
   else{db()->prepare("INSERT INTO ad_placements(creative_id,slot_key,starts_at,ends_at,status,created_by,updated_by) VALUES (?,?,?,?,'draft',?,?)")->execute([$creativeId,$slot,$starts,$ends,(int)$me['id'],(int)$me['id']]);$id=(int)db()->lastInsertId();}
   audit_log('placement_saved','ad_placement',$id,$slot);flash('Placement saved as draft.');
  }elseif($action==='placement_status'){
   require_permission('advertising.manage');$id=(int)($_POST['id']??0);$to=(string)($_POST['status']??'');$placement=query_one('SELECT p.*,cr.status creative_status,c.status campaign_status,c.starts_at campaign_start,c.ends_at campaign_end FROM ad_placements p JOIN ad_creatives cr ON cr.id=p.creative_id JOIN ad_campaigns c ON c.id=cr.campaign_id WHERE p.id=?',[$id]);if(!$placement)throw new RuntimeException('Placement not found.');$from=(string)$placement['status'];$allowed=['draft'=>['active','cancelled'],'active'=>['paused','completed','cancelled'],'paused'=>['active','completed','cancelled']];if(!in_array($to,$allowed[$from]??[],true))throw new RuntimeException('Invalid placement transition.');if($to==='active'&&($placement['creative_status']!=='approved'||$placement['campaign_status']!=='active'||time()<strtotime($placement['campaign_start'])||time()>=strtotime($placement['campaign_end'])||time()<strtotime($placement['starts_at'])||time()>=strtotime($placement['ends_at'])))throw new RuntimeException('Approved creative and active in-date campaign and placement are required.');$s=db()->prepare('UPDATE ad_placements SET status=?,updated_by=?,updated_at='.sql_now().' WHERE id=? AND status=?');$s->execute([$to,(int)$me['id'],$id,$from]);if($s->rowCount()!==1)throw new RuntimeException('Placement status changed before this action completed.');audit_log('placement_status','ad_placement',$id,$from.'>'.$to);flash('Placement status updated.');
  }else throw new RuntimeException('Unknown advertising action.');ad_redirect();
 }catch(Throwable $e){error_log('Advertising operation failed: '.$e->getMessage());$error=$e instanceof PDOException?'Advertising operation could not be completed. Check dates and unique values.':$e->getMessage();}
}

$advertisers=query_all('SELECT * FROM advertisers ORDER BY name');
$campaigns=query_all('SELECT c.*,a.name advertiser,creator.full_name creator_name,approver.full_name approver_name FROM ad_campaigns c JOIN advertisers a ON a.id=c.advertiser_id JOIN users creator ON creator.id=c.created_by LEFT JOIN users approver ON approver.id=c.approved_by ORDER BY c.created_at DESC');
$creatives=query_all('SELECT cr.*,c.name campaign_name,c.status campaign_status,a.name advertiser,creator.full_name creator_name,approver.full_name approver_name FROM ad_creatives cr JOIN ad_campaigns c ON c.id=cr.campaign_id JOIN advertisers a ON a.id=c.advertiser_id JOIN users creator ON creator.id=cr.created_by LEFT JOIN users approver ON approver.id=cr.approved_by ORDER BY cr.created_at DESC');
$placements=query_all('SELECT p.*,cr.title creative_title,c.name campaign_name FROM ad_placements p JOIN ad_creatives cr ON cr.id=p.creative_id JOIN ad_campaigns c ON c.id=cr.campaign_id ORDER BY p.created_at DESC');
$adMetrics=query_all("SELECT p.id,p.slot_key,p.status,cr.title creative_title,c.name campaign_name,COALESCE(SUM(CASE WHEN e.event_type='served' THEN 1 ELSE 0 END),0) served,COALESCE(SUM(CASE WHEN e.event_type='viewable' THEN 1 ELSE 0 END),0) viewable,COALESCE(SUM(CASE WHEN e.event_type='click' THEN 1 ELSE 0 END),0) clicks FROM ad_placements p JOIN ad_creatives cr ON cr.id=p.creative_id JOIN ad_campaigns c ON c.id=cr.campaign_id LEFT JOIN ad_events e ON e.placement_id=p.id GROUP BY p.id,p.slot_key,p.status,cr.title,c.name ORDER BY p.created_at DESC");
$openCampaigns=array_values(array_filter($campaigns,static fn(array $c):bool=>!in_array($c['status'],['completed','cancelled'],true)));
$approvedCreatives=array_values(array_filter($creatives,static fn(array $c):bool=>$c['status']==='approved'));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Advertising Operations · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="admin-body"><main class="admin-content" style="max-width:1280px;margin:auto"><p><a href="<?=e(path('admin/modules.php'))?>">← Management Modules</a></p><div class="admin-section-title"><h1>Advertising Operations<span class="brand-accent">.</span></h1></div><p>Commercial workflow: advertiser → campaign approval → licensed creative review → placement → activation. Creators cannot approve their own campaign or creative.</p><?php if($error):?><div class="form-error" role="alert"><?=e($error)?></div><?php endif;?><?php if($msg=notice()):?><div class="admin-notice" role="status"><?=e($msg)?></div><?php endif;?>

<?php if(can('advertising.manage')):?><div class="workflow-grid"><section class="setting-panel"><h2>1. Add advertiser</h2><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_advertiser"><label>COMPANY NAME<input name="name" maxlength="200" required></label><label>CONTACT EMAIL<input type="email" name="email" required></label><label>BILLING CURRENCY<input name="currency" value="RWF" maxlength="3" pattern="[A-Za-z]{3}" required></label><button>ADD ADVERTISER →</button></form></section><section class="setting-panel"><h2>2. Create campaign</h2><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_campaign"><label>ADVERTISER<select name="advertiser_id" required><?php foreach($advertisers as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></label><label>CAMPAIGN NAME<input name="name" minlength="3" maxlength="200" required></label><label>PRICING MODEL<select name="pricing_model"><option>FIXED</option><option>CPM</option><option>CPC</option></select></label><label>BUDGET (RWF uses whole francs)<input type="number" min="1" name="budget_minor" required></label><label>CURRENCY<input name="currency" value="RWF" maxlength="3" pattern="[A-Za-z]{3}" required></label><label>START<input type="datetime-local" name="starts_at" required></label><label>END<input type="datetime-local" name="ends_at" required></label><button>CREATE CAMPAIGN DRAFT →</button></form></section></div><?php endif;?>

<section class="setting-panel"><h2>3. Campaign approval and activation</h2><?php if(!$campaigns):?><p>No campaigns yet.</p><?php endif;?><?php foreach($campaigns as $c):?><article class="inbox-card"><h3><?=e($c['name'])?></h3><p><?=e($c['advertiser'])?> · <?=e($c['pricing_model'])?> · <?=e($c['currency'].' '.number_format((int)$c['budget_minor']))?> · <b><?=e($c['status'])?></b></p><small><?=e(display_date($c['starts_at']))?> → <?=e(display_date($c['ends_at']))?> · Created by <?=e($c['creator_name'])?><?php if($c['approver_name']):?> · Approved by <?=e($c['approver_name'])?><?php endif;?></small><div class="ops-actions"><?php if(can('advertising.manage')&&$c['status']==='draft'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="submit_campaign"><input type="hidden" name="id" value="<?=$c['id']?>"><button>SUBMIT</button></form><?php endif;?><?php if(can('advertising.approve')&&$c['status']==='pending_approval'&&(int)$c['created_by']!==(int)$me['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve_campaign"><input type="hidden" name="id" value="<?=$c['id']?>"><button>APPROVE CAMPAIGN</button></form><?php endif;?><?php if(can('advertising.manage')&&in_array($c['status'],['approved','active','paused'],true)):?><?php foreach($c['status']==='approved'?['active','cancelled']:($c['status']==='active'?['paused','completed','cancelled']:['active','completed','cancelled']) as $to):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="campaign_status"><input type="hidden" name="id" value="<?=$c['id']?>"><input type="hidden" name="status" value="<?=e($to)?>"><button><?=e(strtoupper($to))?></button></form><?php endforeach;?><?php endif;?></div></article><?php endforeach;?></section>

<?php if(can('advertising.manage')):?><section class="setting-panel"><h2>4. Upload real 60×90 creative</h2><p>JPEG, PNG or WebP; 2:3 ratio (for example 600×900 px); maximum 5 MB. Files remain private until an independent Publisher approves them.</p><form method="post" enctype="multipart/form-data" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_creative"><label>CAMPAIGN<select name="campaign_id" required><?php foreach($openCampaigns as $c):?><option value="<?=$c['id']?>"><?=e($c['advertiser'].' — '.$c['name'].' ['.$c['status'].']')?></option><?php endforeach;?></select></label><label>CREATIVE IMAGE<input type="file" name="creative_image" accept="image/jpeg,image/png,image/webp" required></label><label>ADVERTISEMENT TITLE<input name="title" maxlength="200" required></label><label>ACCESSIBLE ALT TEXT<textarea name="alt_text" maxlength="500" required></textarea></label><label>HTTPS DESTINATION URL<input type="url" name="destination_url" pattern="https://.*" required></label><label>BUTTON TEXT (OPTIONAL)<input name="button_text" maxlength="80" placeholder="Learn more"></label><label>LANGUAGE<select name="locale"><option value="all">English + Kinyarwanda</option><option value="en">English</option><option value="rw">Kinyarwanda</option></select></label><label>DISCLOSURE<select name="disclosure"><option>ADVERTISEMENT</option><option>SPONSORED</option></select></label><label>RIGHTS HOLDER<input name="rights_holder" maxlength="240" required></label><label>LICENCE / CONTRACT REFERENCE<input name="license_reference" maxlength="500" required></label><button>UPLOAD TO PRIVATE REVIEW →</button></form></section><?php endif;?>

<section class="setting-panel"><h2>5. Creative review</h2><?php if(!$creatives):?><p>No creatives uploaded yet.</p><?php endif;?><?php foreach($creatives as $cr):?><article class="inbox-card"><div style="display:grid;grid-template-columns:120px 1fr;gap:18px"><a href="<?=e(path('admin/ad-creative-preview.php?id='.$cr['id']))?>" target="_blank" rel="noopener"><img src="<?=e(path('admin/ad-creative-preview.php?id='.$cr['id']))?>" alt="" style="width:120px;aspect-ratio:2/3;object-fit:cover;border-radius:4px"></a><div><h3><?=e($cr['title'])?></h3><p><?=e($cr['advertiser'].' · '.$cr['campaign_name'])?> · <b><?=e($cr['status'])?></b> · <?=e($cr['locale'])?> · <?=e($cr['disclosure'])?></p><small><?=e($cr['width'].'×'.$cr['height'].' · '.$cr['rights_holder'].' · '.$cr['license_reference'])?><br>Created by <?=e($cr['creator_name'])?><?php if($cr['approver_name']):?> · Reviewed by <?=e($cr['approver_name'])?><?php endif;?></small><?php if($cr['review_note']):?><p class="form-error"><?=e($cr['review_note'])?></p><?php endif;?><p><a href="<?=e($cr['destination_url'])?>" target="_blank" rel="sponsored noopener noreferrer">Test destination ↗</a></p><div class="ops-actions"><?php if(can('advertising.manage')&&in_array($cr['status'],['draft','rejected'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="submit_creative"><input type="hidden" name="id" value="<?=$cr['id']?>"><button>SUBMIT CREATIVE</button></form><?php endif;?><?php if(can('advertising.approve')&&$cr['status']==='pending_review'&&(int)$cr['created_by']!==(int)$me['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve_creative"><input type="hidden" name="id" value="<?=$cr['id']?>"><button>APPROVE CREATIVE</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reject_creative"><input type="hidden" name="id" value="<?=$cr['id']?>"><input name="reason" minlength="10" placeholder="Rejection reason" required><button>REJECT</button></form><?php endif;?></div></div></div><?php if(can('advertising.manage')&&in_array($cr['status'],['draft','rejected'],true)):?><details><summary>Edit creative</summary><form method="post" enctype="multipart/form-data" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="update_creative"><input type="hidden" name="id" value="<?=$cr['id']?>"><label>REPLACE IMAGE (OPTIONAL)<input type="file" name="creative_image" accept="image/jpeg,image/png,image/webp"></label><label>TITLE<input name="title" value="<?=e($cr['title'])?>" maxlength="200" required></label><label>ALT TEXT<textarea name="alt_text" maxlength="500" required><?=e($cr['alt_text'])?></textarea></label><label>DESTINATION URL<input type="url" name="destination_url" value="<?=e($cr['destination_url'])?>" pattern="https://.*" required></label><label>BUTTON TEXT<input name="button_text" value="<?=e($cr['button_text'])?>" maxlength="80"></label><label>LANGUAGE<select name="locale"><?php foreach(['all','en','rw'] as $v):?><option value="<?=$v?>" <?=$cr['locale']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>DISCLOSURE<select name="disclosure"><?php foreach(['ADVERTISEMENT','SPONSORED'] as $v):?><option <?=$cr['disclosure']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>RIGHTS HOLDER<input name="rights_holder" value="<?=e($cr['rights_holder'])?>" required></label><label>LICENCE / CONTRACT REFERENCE<input name="license_reference" value="<?=e($cr['license_reference'])?>" required></label><button>SAVE CHANGES</button></form></details><?php endif;?></article><?php endforeach;?></section>

<?php if(can('advertising.manage')):?><section class="setting-panel"><h2>6. Homepage and sitewide placement</h2><p>Choose one of the four homepage rail positions or the luxury banner displayed before the footer on every public editorial page.</p><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="save_placement"><label>APPROVED CREATIVE<select name="creative_id" required><?php foreach($approvedCreatives as $cr):?><option value="<?=$cr['id']?>"><?=e($cr['advertiser'].' — '.$cr['title'])?></option><?php endforeach;?></select></label><label>POSITION<select name="slot_key"><?php foreach(ad_slots() as $key=>$label):?><option value="<?=e($key)?>"><?=e($label)?></option><?php endforeach;?></select></label><label>START<input type="datetime-local" name="starts_at" required></label><label>EXPIRY<input type="datetime-local" name="ends_at" required></label><button>SAVE PLACEMENT DRAFT →</button></form></section><?php endif;?>

<section class="setting-panel"><h2>7. Placement activation</h2><p>The homepage shows a placement only when the placement and campaign are active, the creative is approved, and current time is inside both date ranges.</p><?php if(!$placements):?><p>No placements yet.</p><?php endif;?><?php foreach($placements as $p):?><article class="inbox-card"><h3><?=e(ad_slots()[$p['slot_key']]??$p['slot_key'])?> · <?=e($p['creative_title'])?></h3><p><?=e($p['campaign_name'])?> · <b><?=e($p['status'])?></b></p><small><?=e(display_date($p['starts_at']))?> → <?=e(display_date($p['ends_at']))?></small><?php if(can('advertising.manage')&&in_array($p['status'],['draft','active','paused'],true)):?><div class="ops-actions"><?php foreach($p['status']==='draft'?['active','cancelled']:($p['status']==='active'?['paused','completed','cancelled']:['active','completed','cancelled']) as $to):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="placement_status"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="status" value="<?=e($to)?>"><button><?=e(strtoupper($to))?></button></form><?php endforeach;?></div><?php endif;?></article><?php endforeach;?></section>
<section class="setting-panel"><h2>8. Privacy-preserving delivery metrics</h2><p>Counts are first-party and store no IP address, referrer or user-agent. A viewable event requires at least 50% of the creative to remain visible for one second. These operational counts are not invoice-grade billing evidence.</p><div style="overflow:auto"><table class="admin-table"><thead><tr><th>Placement</th><th>Campaign</th><th>Status</th><th>Served</th><th>Viewable</th><th>Clicks</th><th>CTR</th></tr></thead><tbody><?php if(!$adMetrics):?><tr><td colspan="7">No placement metrics yet.</td></tr><?php endif;?><?php foreach($adMetrics as $m):$ctr=(int)$m['viewable']>0?((int)$m['clicks']/(int)$m['viewable'])*100:0;?><tr><td><?=e((ad_slots()[$m['slot_key']]??$m['slot_key']).' · '.$m['creative_title'])?></td><td><?=e($m['campaign_name'])?></td><td><?=e($m['status'])?></td><td><?=number_format((int)$m['served'])?></td><td><?=number_format((int)$m['viewable'])?></td><td><?=number_format((int)$m['clicks'])?></td><td><?=e(number_format($ctr,2).'%')?></td></tr><?php endforeach;?></tbody></table></div></section>
</main></body></html>
